sys_script_include.script:
var LearnSphereUtils = Class.create();
LearnSphereUtils.prototype = {
    initialize: function() {
    },
	getInstructorsUser: function() {
		var grInstructorRole = new GlideRecord('sys_user_has_role');
		grInstructorRole.addEncodedQuery('role.name=x_1305322_learns_0.ls_course_instructor^state=active');
		grInstructorRole.query();

		var instructorUsers = [];

		while(grInstructorRole.next()) {
			instructorUsers.push(grInstructorRole.getValue('user'));
		}

		return 'sys_idIN' + instructorUsers;
	},
	getUnregisteredEnrollments: function () {
		var enrollmentsNotToBeShown = [];

		var grEnrollments = new GlideRecord('x_1305322_learns_0_enrollments');
		grEnrollments.addEncodedQuery('opened_byDYNAMIC90d1921e5f510100a9ad2572f2b477fe^state!=4');
		grEnrollments.query();

		while(grEnrollments.next()) {
			enrollmentsNotToBeShown.push(grEnrollments.schedule.sys_id.toString());
		}

		var enrollmentsToBeShown = [];
		var grSchedule = new GlideRecord('x_1305322_learns_0_course_schedules');
		grSchedule.query();

		while(grSchedule.next()) {
			if(enrollmentsNotToBeShown.indexOf(grSchedule.getUniqueValue()) == -1) {
				enrollmentsToBeShown.push("sys_id=" + grSchedule.getUniqueValue().toString() + "^OR");
			}
		}

		return enrollmentsToBeShown.join('');
	},
    type: 'LearnSphereUtils'
};
